impl LookupReferences for ActivityDefinition {
    fn lookup_references(&mut self) -> Vec<Box<&mut dyn ReferenceField>> {
        let mut refs: Vec<Box<&mut dyn ReferenceField>> = Vec::new();
        if let Some(ActivityDefinitionSubject::Reference(ref mut r)) = self
            .0
            .subject
            .as_mut()
        {
            refs.push(Box::new(r));
        }
        for participant in self.0.participant.iter_mut() {
            if let Some(participant) = participant.as_mut() {
                refs.extend(participant.lookup_references());
            }
        }
        if let Some(ActivityDefinitionProduct::Reference(ref mut r)) = self
            .0
            .product
            .as_mut()
        {
            refs.push(Box::new(r));
        }
        for dynamic_value in self.0.dynamic_value.iter_mut() {
            if let Some(dynamic_value) = dynamic_value.as_mut() {
                refs.extend(dynamic_value.lookup_references());
            }
        }
        refs
    }
}
