impl LookupReferences for CarePlan {
    fn lookup_references(&mut self) -> Vec<Box<&mut dyn ReferenceField>> {
        let mut refs: Vec<Box<&mut dyn ReferenceField>> = Vec::new();
        for based_on in self.0.based_on.iter_mut() {
            if let Some(based_on) = based_on.as_mut() {
                refs.push(Box::new(based_on));
            }
        }
        for replaces in self.0.replaces.iter_mut() {
            if let Some(replaces) = replaces.as_mut() {
                refs.push(Box::new(replaces));
            }
        }
        for part_of in self.0.part_of.iter_mut() {
            if let Some(part_of) = part_of.as_mut() {
                refs.push(Box::new(part_of));
            }
        }
        refs.push(Box::new(&mut self.0.subject));
        if let Some(encounter) = self.0.encounter.as_mut() {
            refs.push(Box::new(encounter));
        }
        if let Some(custodian) = self.0.custodian.as_mut() {
            refs.push(Box::new(custodian));
        }
        for contributor in self.0.contributor.iter_mut() {
            if let Some(contributor) = contributor.as_mut() {
                refs.push(Box::new(contributor));
            }
        }
        for care_team in self.0.care_team.iter_mut() {
            if let Some(care_team) = care_team.as_mut() {
                refs.push(Box::new(care_team));
            }
        }
        for supporting_info in self.0.supporting_info.iter_mut() {
            if let Some(supporting_info) = supporting_info.as_mut() {
                refs.push(Box::new(supporting_info));
            }
        }
        for goal in self.0.goal.iter_mut() {
            if let Some(goal) = goal.as_mut() {
                refs.push(Box::new(goal));
            }
        }
        for activity in self.0.activity.iter_mut() {
            if let Some(activity) = activity.as_mut() {
                refs.extend(activity.lookup_references());
            }
        }
        refs
    }
}
