impl LookupReferences for Composition {
    fn lookup_references(&mut self) -> Vec<Box<&mut dyn ReferenceField>> {
        let mut refs: Vec<Box<&mut dyn ReferenceField>> = Vec::new();
        for subject in self.0.subject.iter_mut() {
            if let Some(subject) = subject.as_mut() {
                refs.push(Box::new(subject));
            }
        }
        if let Some(encounter) = self.0.encounter.as_mut() {
            refs.push(Box::new(encounter));
        }
        for author in self.0.author.iter_mut() {
            if let Some(author) = author.as_mut() {
                refs.push(Box::new(author));
            }
        }
        for attester in self.0.attester.iter_mut() {
            if let Some(attester) = attester.as_mut() {
                refs.extend(attester.lookup_references());
            }
        }
        if let Some(custodian) = self.0.custodian.as_mut() {
            refs.push(Box::new(custodian));
        }
        for event in self.0.event.iter_mut() {
            if let Some(event) = event.as_mut() {
                refs.extend(event.lookup_references());
            }
        }
        for section in self.0.section.iter_mut() {
            if let Some(section) = section.as_mut() {
                refs.extend(section.lookup_references());
            }
        }
        refs
    }
}
