impl LookupReferences for ConditionDefinition {
    fn lookup_references(&mut self) -> Vec<Box<&mut dyn ReferenceField>> {
        let mut refs: Vec<Box<&mut dyn ReferenceField>> = Vec::new();
        for observation in self.0.observation.iter_mut() {
            if let Some(observation) = observation.as_mut() {
                refs.extend(observation.lookup_references());
            }
        }
        for medication in self.0.medication.iter_mut() {
            if let Some(medication) = medication.as_mut() {
                refs.extend(medication.lookup_references());
            }
        }
        for precondition in self.0.precondition.iter_mut() {
            if let Some(precondition) = precondition.as_mut() {
                refs.extend(precondition.lookup_references());
            }
        }
        for team in self.0.team.iter_mut() {
            if let Some(team) = team.as_mut() {
                refs.push(Box::new(team));
            }
        }
        for questionnaire in self.0.questionnaire.iter_mut() {
            if let Some(questionnaire) = questionnaire.as_mut() {
                refs.extend(questionnaire.lookup_references());
            }
        }
        for plan in self.0.plan.iter_mut() {
            if let Some(plan) = plan.as_mut() {
                refs.extend(plan.lookup_references());
            }
        }
        refs
    }
}
