impl LookupReferences for DocumentReference {
    fn lookup_references(&mut self) -> Vec<Box<&mut dyn ReferenceField>> {
        let mut refs: Vec<Box<&mut dyn ReferenceField>> = Vec::new();
        for based_on in self.0.based_on.iter_mut() {
            if let Some(based_on) = based_on.as_mut() {
                refs.push(Box::new(based_on));
            }
        }
        if let Some(subject) = self.0.subject.as_mut() {
            refs.push(Box::new(subject));
        }
        for context in self.0.context.iter_mut() {
            if let Some(context) = context.as_mut() {
                refs.push(Box::new(context));
            }
        }
        for author in self.0.author.iter_mut() {
            if let Some(author) = author.as_mut() {
                refs.push(Box::new(author));
            }
        }
        for attester in self.0.attester.iter_mut() {
            if let Some(attester) = attester.as_mut() {
                refs.extend(attester.lookup_references());
            }
        }
        if let Some(custodian) = self.0.custodian.as_mut() {
            refs.push(Box::new(custodian));
        }
        for relates_to in self.0.relates_to.iter_mut() {
            if let Some(relates_to) = relates_to.as_mut() {
                refs.extend(relates_to.lookup_references());
            }
        }
        for content in self.0.content.iter_mut() {
            if let Some(content) = content.as_mut() {
                refs.extend(content.lookup_references());
            }
        }
        refs
    }
}
