impl LookupReferences for Evidence {
    fn lookup_references(&mut self) -> Vec<Box<&mut dyn ReferenceField>> {
        let mut refs: Vec<Box<&mut dyn ReferenceField>> = Vec::new();
        if let Some(EvidenceCiteAs::Reference(ref mut r)) = self.0.cite_as.as_mut() {
            refs.push(Box::new(r));
        }
        for variable_definition in self.0.variable_definition.iter_mut() {
            if let Some(variable_definition) = variable_definition.as_mut() {
                refs.extend(variable_definition.lookup_references());
            }
        }
        for statistic in self.0.statistic.iter_mut() {
            if let Some(statistic) = statistic.as_mut() {
                refs.extend(statistic.lookup_references());
            }
        }
        for certainty in self.0.certainty.iter_mut() {
            if let Some(certainty) = certainty.as_mut() {
                refs.extend(certainty.lookup_references());
            }
        }
        refs
    }
}
