impl LookupReferences for Procedure {
    fn lookup_references(&mut self) -> Vec<Box<&mut dyn ReferenceField>> {
        let mut refs: Vec<Box<&mut dyn ReferenceField>> = Vec::new();
        for based_on in self.0.based_on.iter_mut() {
            if let Some(based_on) = based_on.as_mut() {
                refs.push(Box::new(based_on));
            }
        }
        for part_of in self.0.part_of.iter_mut() {
            if let Some(part_of) = part_of.as_mut() {
                refs.push(Box::new(part_of));
            }
        }
        refs.push(Box::new(&mut self.0.subject));
        if let Some(focus) = self.0.focus.as_mut() {
            refs.push(Box::new(focus));
        }
        if let Some(encounter) = self.0.encounter.as_mut() {
            refs.push(Box::new(encounter));
        }
        if let Some(recorder) = self.0.recorder.as_mut() {
            refs.push(Box::new(recorder));
        }
        if let Some(ProcedureReported::Reference(ref mut r)) = self.0.reported.as_mut() {
            refs.push(Box::new(r));
        }
        for performer in self.0.performer.iter_mut() {
            if let Some(performer) = performer.as_mut() {
                refs.extend(performer.lookup_references());
            }
        }
        if let Some(location) = self.0.location.as_mut() {
            refs.push(Box::new(location));
        }
        for report in self.0.report.iter_mut() {
            if let Some(report) = report.as_mut() {
                refs.push(Box::new(report));
            }
        }
        for focal_device in self.0.focal_device.iter_mut() {
            if let Some(focal_device) = focal_device.as_mut() {
                refs.extend(focal_device.lookup_references());
            }
        }
        for supporting_info in self.0.supporting_info.iter_mut() {
            if let Some(supporting_info) = supporting_info.as_mut() {
                refs.push(Box::new(supporting_info));
            }
        }
        refs
    }
}
