impl LookupReferences for Provenance {
    fn lookup_references(&mut self) -> Vec<Box<&mut dyn ReferenceField>> {
        let mut refs: Vec<Box<&mut dyn ReferenceField>> = Vec::new();
        for target in self.0.target.iter_mut() {
            if let Some(target) = target.as_mut() {
                refs.push(Box::new(target));
            }
        }
        if let Some(location) = self.0.location.as_mut() {
            refs.push(Box::new(location));
        }
        for based_on in self.0.based_on.iter_mut() {
            if let Some(based_on) = based_on.as_mut() {
                refs.push(Box::new(based_on));
            }
        }
        if let Some(patient) = self.0.patient.as_mut() {
            refs.push(Box::new(patient));
        }
        if let Some(encounter) = self.0.encounter.as_mut() {
            refs.push(Box::new(encounter));
        }
        for agent in self.0.agent.iter_mut() {
            if let Some(agent) = agent.as_mut() {
                refs.extend(agent.lookup_references());
            }
        }
        for entity in self.0.entity.iter_mut() {
            if let Some(entity) = entity.as_mut() {
                refs.extend(entity.lookup_references());
            }
        }
        refs
    }
}
