impl LookupReferences for Transport {
    fn lookup_references(&mut self) -> Vec<Box<&mut dyn ReferenceField>> {
        let mut refs: Vec<Box<&mut dyn ReferenceField>> = Vec::new();
        for based_on in self.0.based_on.iter_mut() {
            if let Some(based_on) = based_on.as_mut() {
                refs.push(Box::new(based_on));
            }
        }
        for part_of in self.0.part_of.iter_mut() {
            if let Some(part_of) = part_of.as_mut() {
                refs.push(Box::new(part_of));
            }
        }
        if let Some(focus) = self.0.focus.as_mut() {
            refs.push(Box::new(focus));
        }
        if let Some(r#for) = self.0.r#for.as_mut() {
            refs.push(Box::new(r#for));
        }
        if let Some(encounter) = self.0.encounter.as_mut() {
            refs.push(Box::new(encounter));
        }
        if let Some(requester) = self.0.requester.as_mut() {
            refs.push(Box::new(requester));
        }
        if let Some(owner) = self.0.owner.as_mut() {
            refs.push(Box::new(owner));
        }
        if let Some(location) = self.0.location.as_mut() {
            refs.push(Box::new(location));
        }
        for insurance in self.0.insurance.iter_mut() {
            if let Some(insurance) = insurance.as_mut() {
                refs.push(Box::new(insurance));
            }
        }
        for relevant_history in self.0.relevant_history.iter_mut() {
            if let Some(relevant_history) = relevant_history.as_mut() {
                refs.push(Box::new(relevant_history));
            }
        }
        if let Some(restriction) = self.0.restriction.as_mut() {
            refs.extend(restriction.lookup_references());
        }
        for input in self.0.input.iter_mut() {
            if let Some(input) = input.as_mut() {
                refs.extend(input.lookup_references());
            }
        }
        for output in self.0.output.iter_mut() {
            if let Some(output) = output.as_mut() {
                refs.extend(output.lookup_references());
            }
        }
        refs.push(Box::new(&mut self.0.requested_location));
        refs.push(Box::new(&mut self.0.current_location));
        if let Some(history) = self.0.history.as_mut() {
            refs.push(Box::new(history));
        }
        refs
    }
}
